/**
 * Drafts may omit sender, subject, content and audience until review or send, except that domain-restricted keys must supply a From address on one of their domains. Content is block HTML (see html); the same form is what the dashboard composer reads and writes, so people and agents edit one document. Simple {{name}} personalization works in text and quoted href/alt attributes; values are HTML-escaped and rendered URLs are validated. Durable campaign preparation is bounded and runs in background jobs.
 */
export type CampaignDraft = {
    name: string;
    from?: string | '';
    fromName?: string;
    /**
     * Optional preheader text. Inserted as escaped hidden text into each outgoing HTML snapshot; draft HTML is unchanged. When set, supply HTML without its own duplicate preheader.
     */
    previewText?: string;
    replyTo?: Array<string>;
    region: string;
    /**
     * Regional MX only. False follows the From domain; the displayed region is a hint. A supplied region on create or a changed region on edit pins it. To unpin, pass false and omit region.
     */
    regionPinned?: boolean;
    subject?: string | '';
    attachments?: Array<string>;
    tracking?: boolean;
    audience?: {
        listId?: string;
        segmentId?: string;
        excludeListIds?: Array<string>;
        excludeSegmentIds?: Array<string>;
        /**
         * Send order: contacts whose property equals an earlier value are reviewed and released first; everyone else follows. Useful with paced sending, e.g. { property: "plan", values: ["active", "former"] }.
         */
        priority?: {
            property: string;
            values: Array<string>;
        };
    };
    defaults?: {
        [key: string]: string | number | boolean | null;
    };
    html?: string;
};

/**
 * The current launch: null until the campaign is sent or scheduled, and cleared by a new revision.
 */
export type CampaignDelivery = {
    /**
     * Fixed recipient count frozen at send or schedule.
     */
    total: number;
    /**
     * Recipients whose message was validated.
     */
    prepared: number;
    /**
     * Recipients materialized as immutable email records.
     */
    expanded: number;
    /**
     * Recipients canceled before materialization. Materialized cancellations remain in counts.byStatus.canceled.
     */
    canceled: number;
    /**
     * Why the campaign failed or was canceled by the system.
     */
    error: {
        code: string;
        message: string;
    } | null;
    pacing: {
        /**
         * Maximum recipients released per rolling 24-hour window; null means no daily cap.
         */
        perDay: number | null;
        /**
         * Pause automatically when bounce or complaint rates exceed safe thresholds.
         */
        autoPause: boolean;
        /**
         * Maximum fraction of the SES per-second send rate this campaign uses; 1 is the full rate.
         */
        rateShare: number;
        windowStartedAt: string | null;
        /**
         * Recipients released in the current 24-hour window.
         */
        windowExpanded: number;
        /**
         * When the next 24-hour window opens, when a daily cap is set.
         */
        nextWindowAt: string | null;
    };
    pausedAt: string | null;
    pauseReason: {
        code: string;
        message: string;
    } | null;
    /**
     * After a resumed list-probe quarantine: the rest goes only to contacts this workspace delivered to before; the others are counted in canceled.
     */
    deliveredOnly: boolean;
    /**
     * Why releasing recipients is currently held, and the best estimate of until when. list_probe: Hosted sent the first recipients (the list probe) and waits for their bounces and complaints before releasing the rest.
     */
    waiting: {
        reason: 'pacing_window' | 'ses_daily_quota' | 'hosted_daily_quota' | 'list_probe' | 'balance';
        until: string;
    } | null;
} | null;

