export type Inbox = {
    /**
     * Inbox ID. It also works as addressId on /v1/inbound endpoints, such as replying in a thread.
     */
    id: string;
    kind: 'inbox';
    /**
     * persistent: a real address kept until explicitly deleted. ephemeral: a real address on one of your active receiving domains. sandbox: an address on a .invalid host that receives nothing from the internet; fill it with POST /v1/inboxes/{id}/simulate.
     */
    type: 'ephemeral' | 'sandbox' | 'persistent';
    /**
     * The address to give the sender or sign-up form.
     */
    address: string;
    domain: string;
    name: string | null;
    metadata: {
        [key: string]: unknown;
    };
    clientId: string | null;
    /**
     * active: receiving. expired: in its grace period; new mail is held. deleting: erased at the next hourly sweep.
     */
    status: 'active' | 'expired' | 'deleting';
    createdAt: string;
    /**
     * When the inbox stops delivering mail.
     */
    expiresAt: string | null;
    /**
     * When the inbox, its mail and its keys are erased.
     */
    deleteAfter: string | null;
    retention: {
        mode: 'forever' | 'ephemeral';
    };
    limits: {
        messages: number | null;
        bytes: number | null;
    };
    send: {
        enabled: boolean;
        perDay: number;
        replyOnly: true;
    };
    usage: {
        /**
         * Messages stored, including held ones.
         */
        messages: number;
        /**
         * Bytes stored, including held mail.
         */
        bytes: number;
        /**
         * Messages stored but not delivered (over a limit or after expiry). List them with include=held.
         */
        held: number;
        unread: number;
        lastMessageAt: string | null;
    };
};

