export type LogEntry = {
    /**
     * Email ID for sent mail (getEmail); message ID for received mail (getInboundMessage).
     */
    id: string;
    direction: 'sent' | 'received';
    /**
     * Received mail and sent mailbox replies can contain external sender content.
     */
    untrustedContent: boolean;
    /**
     * When the email was created (sent) or received.
     */
    at: string;
    /**
     * Sent: the email status. Received: received, or spam when flagged (spam is shown to administrators only).
     */
    status: string;
    from: {
        name: string | null;
        address: string;
    };
    /**
     * Sent: the To recipients. Received: the addresses in the To header.
     */
    to: Array<string>;
    subject: string;
    /**
     * Sent mail only.
     */
    stream: 'transactional' | 'marketing' | null;
    campaignId: string | null;
    /**
     * Sent through the SES mailbox simulator. Always false for received mail.
     */
    simulated: boolean;
    /**
     * Received mail only.
     */
    attachmentCount: number | null;
    /**
     * Received mail only.
     */
    threadId: string | null;
    /**
     * Received mail only: the receiving addresses it was delivered to that the caller can read. Empty for unrouted mail.
     */
    addresses: Array<{
        id: string;
        address: string;
    }> | null;
    /**
     * Null for received mail unless the caller is an administrator.
     */
    region: string | null;
    /**
     * Received mail, administrators only: the SMTP envelope recipients.
     */
    envelopeTo: Array<string> | null;
};

export type InboundOverview = {
    /**
     * Routes per kind, after the domain and q filters and before kind and origin.
     */
    counts: {
        address: number;
        /**
         * Addresses a catch-all created (origin auto).
         */
        auto: number;
        route: number;
        pattern: number;
        catch_all: number;
        inbox: number;
    };
    routes: {
        data: Array<InboundOverviewRoute>;
        nextCursor: string | null;
    };
    rituals: Array<{
        key: string;
        /**
         * Endpoint names it can call.
         */
        calls: Array<string>;
        /**
         * Inbox keys it can deliver to.
         */
        delivers: Array<string>;
        omens: Array<string>;
        /**
         * Address IDs or addresses it runs on.
         */
        attachedTo: Array<string>;
    }>;
    /**
     * At most 100 endpoints (by name) and 100 inbound webhooks.
     */
    endpoints: Array<InboundOverviewEndpoint>;
    /**
     * True when the workspace has more endpoints or inbound webhooks than listed. Read them all with listEndpoints and listInboundWebhooks, following nextCursor until it is null.
     */
    endpointsTruncated: boolean;
    /**
     * Every domain with its receiving status, including domains that only send.
     */
    domains: Array<InboundOverviewDomain>;
    /**
     * False for members and scoped keys: they see their addresses, without routes, rituals, endpoints or domains.
     */
    manage: boolean;
};

export type InboundOverviewRoute = {
    /**
     * Address ID, route ID, <addressId>:<pattern> for an address pattern, or default:<domainId> for a domain default.
     */
    id: string;
    kind: 'address' | 'inbox' | 'route' | 'pattern' | 'catch_all';
    /**
     * The address or pattern mail is sent to.
     */
    match: string;
    host: string;
    address: InboundAddress & ({
        [key: string]: unknown;
    } | null);
    /**
     * The explicit route for this match, when one exists.
     */
    route: {
        id: string;
        enabled: boolean;
        to: Array<string> | 'drop';
    } | null;
    /**
     * The domain default for unknown recipients, on a domain-default row.
     */
    catchAll: 'store' | 'create_address' | null;
    /**
     * Rituals attached to this address or alias, in the order they run.
     */
    rituals: Array<string>;
    /**
     * Where its mail goes: routing first, then active webhook subscribers, then what attached rituals can send it to, then paused subscribers. Routing and ritual targets are always complete; subscribers are listed up to 50, active ones first.
     */
    to: Array<InboundOverviewTarget>;
    /**
     * Targets in the complete list. Larger than to.length only when toTruncated.
     */
    toTotal: number;
    /**
     * True when the address has more than 50 webhook subscribers, so to is not the whole list.
     */
    toTruncated: boolean;
    /**
     * When toTruncated: the API path that lists every webhook subscribed to this address (listInboundWebhooks with addressId and eventType=message.received; follow nextCursor).
     */
    toMore: string | null;
};

export type InboundOverviewTarget = {
    /**
     * inbox: the address keeps the thread. webhook, slack, discord, forward: an endpoint or an inbound webhook. store: kept without an inbox. drop: not stored. create_address: the domain creates an address for the recipient.
     */
    type: 'inbox' | 'webhook' | 'slack' | 'discord' | 'forward' | 'store' | 'drop' | 'create_address';
    /**
     * Address ID for an inbox, webhook ID (mwh_…) for an endpoint or inbound webhook; null for store, drop and create_address.
     */
    id: string | null;
    /**
     * Display name, endpoint name or address.
     */
    name: string;
    /**
     * Where it delivers. Webhook, Slack and Discord URLs are write-only; only the last four characters are shown.
     */
    detail: string | null;
    /**
     * The ritual that sends mail here. A ritual may do so for only some mail; null when routing always does.
     */
    via: string | null;
    /**
     * Endpoint status; paused for a paused inbound webhook; null for inboxes and outcomes.
     */
    status: 'ready' | 'pending' | 'expired' | 'declined' | 'paused' | null;
};

export type InboundOverviewEndpoint = {
    /**
     * Webhook ID (mwh_…) that delivers for it.
     */
    id: string;
    /**
     * endpoint: a named endpoint rituals call (and routes can name). inbound_webhook: a webhook created with createInboundWebhook.
     */
    source: 'endpoint' | 'inbound_webhook';
    name: string;
    type: 'webhook' | 'slack' | 'discord' | 'forward';
    status: 'ready' | 'pending' | 'expired' | 'declined' | 'paused';
    /**
     * Where it delivers; URLs are write-only (last four characters).
     */
    target: string;
    /**
     * How a ritual calls an endpoint; null for an inbound webhook.
     */
    call: string | null;
    /**
     * Events an inbound webhook subscribes to; empty for endpoints and route-only webhooks.
     */
    eventTypes: Array<string>;
    /**
     * Routes that name it.
     */
    routes: number;
    /**
     * Rituals that call it.
     */
    rituals: Array<string>;
};

export type InboundOverviewDomain = {
    /**
     * Nightmail domain ID.
     */
    id: string;
    /**
     * Receiving host: the domain, or the subdomain it receives at.
     */
    name: string;
    status: 'off' | 'provisioning' | 'waiting_for_mx' | 'active' | 'disabling' | 'disabled' | 'failed';
    catchAll: 'create_address' | 'store';
};

export type UpdateInboundThread = {
    /**
     * Opaque inbound address ID (mbx_…).
     */
    addressId?: string;
    read?: boolean;
    archived?: boolean;
    starred?: boolean;
    trashed?: boolean;
    spam?: boolean;
    addLabels?: Array<string>;
    removeLabels?: Array<string>;
};

export type CreateInboundThread = {
    /**
     * Defaults to the public address if configured, otherwise the primary receiving address. Address keys may use only addresses owned by this mailbox. Administrators may use any address on a domain registered in Nightmail for the receiving region; replies still return to whatever address the recipient answers.
     */
    from?: string;
    text?: string;
    html?: string;
    /**
     * Up to 20 files, 8 MiB combined. Any type Amazon SES delivers (executables and scripts are refused).
     */
    attachments?: Array<InboundAttachmentInput>;
    replyTo?: Array<string>;
    /**
     * Extra MIME headers, 8 KB total. The 15-header limit includes generated headers (two for marketing and any mailbox threading headers). Any name is allowed except headers Nightmail controls: From, Sender, Reply-To, Return-Path, To, Cc, Bcc, Subject, Date, Message-ID, MIME-Version, Content-*, DKIM-*, ARC-*, Authentication-Results, Received*, Resent-*, X-SES-*, List-Unsubscribe*, Auto-Submitted, and reply, receipt, trace and transport headers (Mail-Reply-To, Mail-Followup-To, Followup-To, Disposition-Notification-*, Return-Receipt-To, Errors-To, Bounces-To, Delivered-To, X-Original-To, DomainKey-*, Feedback-ID, TLS-Required, BIMI-*, Autocrypt*, OpenPGP). In-Reply-To and References must be <id@domain> Message-IDs and thread the message in the recipient's mail client.
     */
    headers?: Array<{
        name: string;
        value: string;
    }>;
    /**
     * Adds an RFC 3834 Auto-Submitted header so other automated systems do not reply to this message.
     */
    autoSubmitted?: 'auto-generated' | 'auto-replied';
    /**
     * Opaque inbound address ID (mbx_…).
     */
    addressId: string;
    to: Array<string>;
    cc?: Array<string>;
    bcc?: Array<string>;
    subject: string;
};

export type InboundAttachmentInput = {
    filename: string;
    /**
     * Base64; line breaks are accepted.
     */
    content: string;
    contentType?: string;
    disposition?: 'attachment' | 'inline';
    contentId?: string;
} | {
    /**
     * A received attachment in this mailbox (matt_…) or a Nightmail attachment upload (attachment_…).
     */
    id: string;
};

export type ReplyToInboundThread = {
    /**
     * Defaults to the public address if configured, otherwise the primary receiving address. Address keys may use only addresses owned by this mailbox. Administrators may use any address on a domain registered in Nightmail for the receiving region; replies still return to whatever address the recipient answers.
     */
    from?: string;
    text?: string;
    html?: string;
    /**
     * Up to 20 files, 8 MiB combined. Any type Amazon SES delivers (executables and scripts are refused).
     */
    attachments?: Array<InboundAttachmentInput>;
    replyTo?: Array<string>;
    /**
     * Extra MIME headers, 8 KB total. The 15-header limit includes generated headers (two for marketing and any mailbox threading headers). Any name is allowed except headers Nightmail controls: From, Sender, Reply-To, Return-Path, To, Cc, Bcc, Subject, Date, Message-ID, MIME-Version, Content-*, DKIM-*, ARC-*, Authentication-Results, Received*, Resent-*, X-SES-*, List-Unsubscribe*, Auto-Submitted, and reply, receipt, trace and transport headers (Mail-Reply-To, Mail-Followup-To, Followup-To, Disposition-Notification-*, Return-Receipt-To, Errors-To, Bounces-To, Delivered-To, X-Original-To, DomainKey-*, Feedback-ID, TLS-Required, BIMI-*, Autocrypt*, OpenPGP). In-Reply-To and References must be <id@domain> Message-IDs and thread the message in the recipient's mail client.
     */
    headers?: Array<{
        name: string;
        value: string;
    }>;
    /**
     * Adds an RFC 3834 Auto-Submitted header so other automated systems do not reply to this message.
     */
    autoSubmitted?: 'auto-generated' | 'auto-replied';
    /**
     * Opaque inbound address ID (mbx_…).
     */
    addressId?: string;
    /**
     * Nightmail message ID (msg_…) of a visible message in this thread.
     */
    replyToMessageId?: string;
    /**
     * Check the final To, Cc and Bcc against these reviewed address sets; never overrides recipients. A mismatch returns 409 INBOUND_RECIPIENTS_CHANGED.
     */
    expectedRecipients?: {
        to: Array<string>;
        cc: Array<string>;
        bcc: Array<string>;
    };
    /**
     * Also copy everyone else on the original message.
     */
    replyAll?: boolean;
    /**
     * Override the computed recipients.
     */
    to?: Array<string>;
    cc?: Array<string>;
    bcc?: Array<string>;
    /**
     * Defaults to "Re: <original subject>".
     */
    subject?: string;
    /**
     * Append the original message as quoted text.
     */
    quote?: boolean;
    /**
     * Reply even when the original is automated or the recipient is a no-reply address.
     */
    allowAutomated?: boolean;
};

export type InboundEventPage = {
    data: Array<InboundEvent>;
    /**
     * Pass as after on the next call.
     */
    cursor: string;
};

export type InboundEvent = {
    id: string;
    cursor: string;
    type: 'message.received' | 'message.junk' | 'message.stored' | 'message.queued' | 'message.sent' | 'message.delivered' | 'message.delayed' | 'message.bounced' | 'message.complained' | 'message.failed' | 'thread.updated' | 'address.created' | 'address.deleted' | 'inbox.created' | 'inbox.deleted' | 'message.held' | 'inbox.quota_exceeded';
    createdAt: string;
    threadId: string | null;
    messageId: string | null;
    data: {
        /**
         * Reason recorded when this send was suppressed. For a multi-recipient send blocked locally, this is the first blocked recipient in To, Cc, Bcc order.
         */
        suppressionReason?: string;
        [key: string]: unknown;
    };
    /**
     * Receiving address ID at the time of the event; null for workspace events.
     */
    addressId: string | null;
};

export type InboundKeySecret = InboundKey & {
    secret: string;
};

export type InboundKey = {
    id: string;
    name: string;
    prefix: string;
    addressIds: Array<string> | null;
    permissions: Array<'read' | 'send' | 'modify' | 'create'>;
    createdAt: string;
    lastUsedAt: string | null;
    revokedAt: string | null;
};

export type CreateInboundKey = {
    name: string;
    permissions?: Array<'read' | 'send' | 'modify' | 'create'>;
    addressIds?: Array<string>;
};

export type InboundKeyPage = {
    data: Array<InboundKey>;
    nextCursor: string | null;
};

export type InboundWebhookSecret = InboundWebhook & {
    secret: string;
    /**
     * inbound format: the X-Webhook-Verification-Token value.
     */
    verificationToken?: string;
};

export type InboundWebhook = {
    id: string;
    /**
     * Write-only HTTPS endpoint. Only the last four characters are shown; omit url on update to keep the saved URL.
     */
    url: string;
    description: string;
    eventTypes: Array<'message.received' | 'message.junk' | 'message.stored' | 'message.queued' | 'message.sent' | 'message.delivered' | 'message.delayed' | 'message.bounced' | 'message.complained' | 'message.failed' | 'thread.updated' | 'address.created' | 'address.deleted' | 'inbox.created' | 'inbox.deleted' | 'message.held' | 'inbox.quota_exceeded'>;
    paused: boolean;
    /**
     * Configured names only for readers. Managers also see a masked hint and the time the header list was last replaced.
     */
    headers: Array<{
        name: string;
        hint?: string;
        updatedAt?: string;
    }>;
    createdAt: string;
    updatedAt: string;
    addressIds: Array<string> | null;
    /**
     * Stable key you choose (lowercase letters, digits, hyphens). Config files refer to inbox:<key> and webhook:<key>.
     */
    key: string | null;
    /**
     * Display name; sent as endpoint.name in the inbound format.
     */
    name: string | null;
    /**
     * bane (default): Nightmail's thin signed event. inbound: inbound.new's email.received body with its X-Webhook-Verification-Token, X-Endpoint-ID, X-Webhook-Event and X-Webhook-Timestamp headers, plus Nightmail's signature headers. Attachment downloadUrl and rawUrl need an admin API key.
     */
    format: 'bane' | 'inbound';
    /**
     * include delivers junk mail (SES spam verdict not PASS) as message.junk, or with spam.isJunk in the inbound format. Defaults to skip for bane and include for inbound.
     */
    junk: 'skip' | 'include';
    /**
     * bane format: also embed the message (text and HTML up to 256 KiB, attachment metadata) and raw MIME in message events. The signed JSON is capped at 512 KiB; fetch omitted content by URL.
     */
    include: Array<'message' | 'raw'>;
    /**
     * Seconds to wait for a 2xx response. Default 5.
     */
    timeoutSeconds: number;
    /**
     * Retries after a failed attempt, backing off from 15 seconds to 12 hours. Default 9 for bane, 3 for inbound.
     */
    retryAttempts: number;
};

export type CreateInboundWebhook = {
    /**
     * Stable key you choose (lowercase letters, digits, hyphens). Config files refer to inbox:<key> and webhook:<key>.
     */
    key?: string | null;
    /**
     * Display name; sent as endpoint.name in the inbound format.
     */
    name?: string | null;
    /**
     * bane (default): Nightmail's thin signed event. inbound: inbound.new's email.received body with its X-Webhook-Verification-Token, X-Endpoint-ID, X-Webhook-Event and X-Webhook-Timestamp headers, plus Nightmail's signature headers. Attachment downloadUrl and rawUrl need an admin API key.
     */
    format?: 'bane' | 'inbound';
    /**
     * include delivers junk mail (SES spam verdict not PASS) as message.junk, or with spam.isJunk in the inbound format. Defaults to skip for bane and include for inbound.
     */
    junk?: 'skip' | 'include';
    /**
     * bane format: also embed the message (text and HTML up to 256 KiB, attachment metadata) and raw MIME in message events. The signed JSON is capped at 512 KiB; fetch omitted content by URL.
     */
    include?: Array<'message' | 'raw'>;
    /**
     * Seconds to wait for a 2xx response. Default 5.
     */
    timeoutSeconds?: number;
    /**
     * Retries after a failed attempt, backing off from 15 seconds to 12 hours. Default 9 for bane, 3 for inbound.
     */
    retryAttempts?: number;
    url: string;
    description?: string;
    /**
     * Events to subscribe to. [] makes a route-only webhook: it receives only mail a route sends to it.
     */
    eventTypes?: Array<'message.received' | 'message.junk' | 'message.stored' | 'message.queued' | 'message.sent' | 'message.delivered' | 'message.delayed' | 'message.bounced' | 'message.complained' | 'message.failed' | 'thread.updated' | 'address.created' | 'address.deleted' | 'inbox.created' | 'inbox.deleted' | 'message.held' | 'inbox.quota_exceeded'>;
    paused?: boolean;
    /**
     * Write-only custom HTTP request headers, e.g. Authorization. Up to 10 unique names (case-insensitive) and 8192 UTF-8 bytes of names and values. Omit on update to keep, supply the complete list to replace, or [] to clear. Transport, Cookie and Nightmail delivery headers are reserved.
     */
    headers?: Array<{
        name: string;
        value: string;
    }>;
    /**
     * Only events for these receiving addresses; null for all.
     */
    addressIds?: Array<string> | null;
};

