export type ProviderConnection = {
    id: string;
    kind: 'shared' | 'byo';
    region: string;
    /**
     * awaiting_role: waiting for the BYO stack. provisioning: verifying regional resources and importing verified domains. ready: sending allowed once the tenant is ready. failed: the last setup attempt failed; verify again.
     */
    state: 'awaiting_role' | 'scanning' | 'ready_to_import' | 'provisioning' | 'ready' | 'failed' | 'disconnecting';
    /**
     * Hosted only: the SES tenant that isolates this workspace. Sends are rejected with TENANT_NOT_READY until it is ready. BYO connections are always ready.
     */
    tenant: 'pending' | 'ready' | 'failed';
    /**
     * Number of currently claimed domains imported from this BYO account.
     */
    importedDomains: number;
    awsAccountId: string | null;
    roleArn: string | null;
    templateVersion: string | null;
    quickCreateUrl: string | null;
    scan?: {
        revision: number;
        cursor: {
            checked: number;
            total: number;
        };
        state: 'awaiting_role' | 'failed' | 'scanning' | 'partial' | 'ready_to_import';
        error: string | null;
        alreadySendsEmail: boolean | null;
        regions: Array<{
            region: string;
            regionLabel: string;
            scanState: string;
            scanError: string | null;
            sendingState: string;
            receivingState: string;
            error: string | null;
            facts: {
                production?: boolean;
                sendingEnabled?: boolean;
                max24HourSend?: number;
                maxSendRate?: number;
                sentLast24Hours?: number;
                configurationSets?: {
                    [key: string]: {
                        installation: boolean | null;
                    };
                };
                receiving?: {
                    supported: boolean;
                    set: string | null;
                    rules: Array<{
                        name: string;
                        enabled: boolean;
                        recipients: Array<string>;
                        actions: Array<string>;
                    }>;
                };
            };
            resources: Array<{
                kind: string;
                resource: string;
                target?: string;
                state?: 'creating' | 'created';
            }>;
            pending: Array<{
                domain: string;
                importing: boolean;
                error: string | null;
            }>;
            failedIntents: Array<{
                domain: string;
                importing: boolean;
                error: string;
            }>;
        }>;
    };
    candidates?: Array<{
        id: string;
        domain: string;
        region: string;
        regionLabel: string;
        selectable: boolean;
        status: 'verified' | 'signing_pending' | 'not_verified' | 'incomplete' | 'already_bound' | 'overlap';
        sandbox: boolean | null;
        defaultConfigurationSet: string | null;
        dkimStatus: string | null;
        signingOrigin: string | null;
        mailFromDomain: string | null;
        overlap: boolean;
    }>;
    cleanup?: {
        operationId: string;
        lastError: {
            region: string | null;
            code: string;
        } | null;
        remaining: Array<{
            region: string;
            resources: Array<{
                kind: string;
                resource: string;
                target?: string;
                state?: 'creating' | 'created';
            }>;
        }>;
        retain: Array<string>;
    };
};

export type ConnectionRegions = {
    shared: Array<string>;
    byo: Array<string>;
};

export type CreateConnection = {
    kind: 'shared' | 'byo';
    region?: string;
    awsAccountId?: string;
};

export type PublicStats = {
    /**
     * The end of the last whole UTC hour the figures cover. They change at most once an hour; responses are cached for up to 60 seconds.
     */
    generatedAt: string;
    /**
     * False until at least 10 workspaces have sent mail in the last 30 days. Every figure is then null and regions is empty, so the figures never describe a single customer.
     */
    available: boolean;
    /**
     * Emails Amazon SES accepted in the last 30 whole days of hours, rounded to two significant figures (to the nearest 10 below 100). Simulated, suppressed and rejected mail is excluded. Email history is kept for 30 days, so there is no all-time total.
     */
    acceptedLast30Days: number | null;
    /**
     * Emails Amazon SES accepted in the last whole UTC hour, rounded the same way. The last entry of acceptedHourly.
     */
    acceptedLastHour: number | null;
    /**
     * Accepted emails per whole UTC hour over the last 24 hours, oldest first, rounded. Null for an hour in which fewer than 3 workspaces sent.
     */
    acceptedHourly: Array<number | null>;
    /**
     * delivered ÷ (delivered + bounced) for emails created in the last 30 days, each email counted once, to three decimals. Null without outcomes.
     */
    deliveryRate: number | null;
    /**
     * Median time from API acceptance to Amazon SES acceptance for the most recent 5,000 direct, unscheduled sends in the last 24 whole hours, to the nearest 10 ms. Null without samples from at least 3 workspaces.
     */
    medianSendLatencyMs: number | null;
    /**
     * AWS regions that accepted mail in the last 30 days. Hosted installations list only their shared sending regions.
     */
    regions: Array<string>;
};

export type OverviewSetup = {
    domains: DomainPage & ({
        [key: string]: unknown;
    } | null);
    /**
     * Null when listApiKeys would refuse the caller: it needs unrestricted manage, and agent tokens never list keys.
     */
    apiKeys: {
        /**
         * Unrevoked API keys.
         */
        active: number;
    } | null;
    emails: {
        /**
         * Whether any email the caller can read exists. Same scope as listEmails: a domain-restricted key sees only direct sends from its domains.
         */
        any: boolean;
    };
    /**
     * Null when listWebhooks would refuse the caller: members and domain-restricted keys.
     */
    webhooks: {
        /**
         * Outbound webhooks, paused ones included.
         */
        total: number;
    } | null;
    /**
     * Null unless listWorkspaceInvitations would answer: an owner or admin dashboard session on a hosted installation.
     */
    invitations: {
        /**
         * Pending, unexpired invitations.
         */
        pending: number;
    } | null;
};

export type AuditEntry = {
    /**
     * Stable ID of the entry; audit entries are prefixed aud_, ledger lines bill_, enforcement events enf_.
     */
    id: string;
    /**
     * When it happened (ISO 8601, UTC).
     */
    at: string;
    /**
     * What happened, as <area>.<verb>: api_key.create, member.role_change, domain.delete, support.view.
     */
    action: string;
    actor: {
        /**
         * member is a signed-in person; support is Nightmail support reading with your permission; system is Nightmail itself.
         */
        type: 'member' | 'api_key' | 'mcp_grant' | 'agent_token' | 'inbox_key' | 'app_password' | 'operator' | 'support' | 'system' | 'stripe';
        /**
         * The member user ID, key ID, grant ID or support grant ID.
         */
        id: string | null;
        /**
         * A short display name for the actor, such as a key name, or null.
         */
        label: string | null;
        /**
         * The member’s email address, for member actors.
         */
        email: string | null;
    };
    /**
     * Where the action came from: dashboard, api, mcp, support, job, webhook.
     */
    via: string;
    /**
     * The object acted on.
     */
    target: {
        type: string;
        id: string | null;
    } | null;
    /**
     * The member the event concerns when it is not the actor: the member whose role changed or whose support request let Nightmail support in.
     */
    subject: {
        userId: string;
        email: string | null;
    } | null;
    /**
     * Before and after, with secrets and message content removed.
     */
    summary: {
        [key: string]: unknown;
    };
    reason: string | null;
    /**
     * The x-request-id of the API request that made the change.
     */
    requestId: string | null;
    /**
     * The client network (/24 or /48), never the full address.
     */
    network: string | null;
    /**
     * The client family, such as "Chrome 131 on macOS".
     */
    client: string | null;
};

export type SupportHandoff = {
    /**
     * The support reference (sho_…). Quote it to support.
     */
    id: string;
    /**
     * Where to continue with support, carrying the signed handoff; null when no support site is configured.
     */
    url: string | null;
    /**
     * The signed handoff (EdDSA JWS, 10 minutes), or null when signing is not configured.
     */
    token: string | null;
    /**
     * Until when support can use this handoff to open read access (30 minutes, once).
     */
    expiresAt: string;
    shareContent: boolean;
};

export type SupportContext = {
    grant: {
        id: string;
        ticketRef: string;
        expiresAt: string;
        /**
         * Whether this request may read email bodies (the customer opted in).
         */
        contentShared: boolean;
        /**
         * The one workspace whose email bodies this request may read, or null.
         */
        contentWorkspaceId: string | null;
    };
    user: {
        id: string;
        name: string | null;
        email: string | null;
        createdAt: string | null;
    };
    workspaces: Array<SupportWorkspace>;
    /**
     * Up to 50 domains across the workspaces.
     */
    domains: Array<SupportDomain>;
    recentFailures: {
        since: string;
        /**
         * Failed, rejected, suppressed and bounced sends in the last 24 hours, by code.
         */
        sends: Array<{
            [key: string]: unknown;
        }>;
        /**
         * Bounce, complaint and reject events in the last 24 hours, by reason.
         */
        bounces: Array<{
            [key: string]: unknown;
        }>;
        /**
         * Webhook deliveries that failed in the last 24 hours, by webhook.
         */
        webhookDeliveries: Array<{
            [key: string]: unknown;
        }>;
        /**
         * Nightmail does not store failed sign-ins or rejected API keys; look up a request ID instead.
         */
        authErrors: null;
    };
    standing: Array<SupportStanding>;
    /**
     * The last 20 customer-visible audit entries (owner and admin workspaces).
     */
    recentActivity: Array<AuditEntry>;
    /**
     * Paused sending and paused campaigns.
     */
    openEnforcement: Array<{
        workspaceId: string;
        kind: string;
        since: string | null;
        reason: string | null;
    }>;
    /**
     * What the customer sent from "Contact support", if the grant came from it.
     */
    handoff: {
        id: string;
        page: string | null;
        requestIds: Array<string>;
        message: string | null;
        createdAt: string;
    } | null;
    links: {
        /**
         * Request IDs to look up with /v1/support/requests/{requestId}.
         */
        requestIds: Array<string>;
    };
};

export type SupportWorkspace = {
    id: string;
    name: string;
    /**
     * The customer’s role in this workspace.
     */
    role: 'owner' | 'admin' | 'member';
    createdAt: string;
    /**
     * The sending connection, or null when none is set up.
     */
    sending: {
        /**
         * shared (Nightmail Hosted) or byo (their own AWS).
         */
        kind: string;
        region: string;
        state: string | null;
        paused: boolean;
        pauseReason: string | null;
        dailyLimitOverride: number | null;
    } | null;
    /**
     * How many of each resource the workspace has: domains, apiKeys, webhooks, inboxes, addresses, routes, endpoints, campaigns, templates, contacts (counted up to 100,000).
     */
    counts: {
        [key: string]: number;
    };
};

export type SupportDomain = {
    workspaceId: string;
    id: string;
    name: string;
    region: string | null;
    createdAt: string | null;
    /**
     * pending, verified, failed or lost.
     */
    sending: string | null;
    dkim: string | null;
    mailFrom: string | null;
    dmarc: string | null;
    /**
     * off, pending, active or lost.
     */
    receiving: string | null;
    lostSince: string | null;
};

export type SupportStanding = {
    workspaceId: string;
    connection: {
        [key: string]: unknown;
    } | null;
    limits: {
        [key: string]: unknown;
    };
    /**
     * The sender standing (step, reasons, score, daily limit) where the reputation system is enabled.
     */
    standing: {
        [key: string]: unknown;
    } | null;
    /**
     * Sent mail in the last 24 hours by status (counted up to 50,000).
     */
    last24h: {
        [key: string]: number;
    };
};

export type SupportEmail = {
    workspaceId: string;
    id: string;
    direction: 'sent' | 'received';
    at: string;
    from: string;
    to: Array<string>;
    subject: string;
    status: string;
    errorCode: string | null;
    suppressionReason: string | null;
    campaignId: string | null;
    kind: string | null;
    simulated: boolean | null;
    /**
     * The SES message ID, for provider-side lookups.
     */
    providerMessageId: string | null;
};

export type SupportEmailDetail = SupportEmail & {
    /**
     * Delivery events for a sent email, oldest first.
     */
    events: Array<SupportDeliveryEvent>;
    /**
     * SPF, DKIM and DMARC verdicts of a received email.
     */
    authentication: {
        [key: string]: unknown;
    } | null;
    /**
     * The body, only when the customer shared message content with this request and the email is in that workspace (grant.contentWorkspaceId); otherwise null.
     */
    content: {
        subject: string;
        text: string | null;
        html: string | null;
    } | null;
};

export type SupportDeliveryEvent = {
    workspaceId: string;
    id: string;
    emailId: string;
    /**
     * send, delivery, bounce, complaint, reject, open, click…
     */
    type: string;
    at: string;
    /**
     * The provider’s event detail (bounce type and diagnostic, complaint feedback type).
     */
    detail: {
        [key: string]: unknown;
    };
};

export type SupportWebhookDelivery = {
    workspaceId: string;
    id: string;
    /**
     * email: sending events; inbound: received mail.
     */
    source: 'email' | 'inbound';
    webhookId: string;
    /**
     * The last four characters of the URL; URLs are credentials.
     */
    endpoint: string;
    eventType: string | null;
    status: string;
    attempts: number;
    lastStatusCode: number | null;
    lastError: string | null;
    createdAt: string;
    updatedAt: string;
};

export type SupportStandingDetail = SupportStanding & {
    /**
     * The last 60 days.
     */
    history: {
        /**
         * The published daily score, quality, limit and step, with the day’s real mail (accepted, hard-bounced, complained, screen-rejected), oldest first. The only source for days older than the 30 days mail is kept.
         */
        days: Array<{
            day: string;
            score: number | null;
            quality: number | null;
            limit: number | null;
            step: string | null;
            accepted: number;
            bounced: number;
            complained: number;
            rejected: number;
        }>;
        /**
         * Changes of standing (ladder steps, limit bands, quarantines, releases), newest first, at most 50.
         */
        changes: Array<{
            at: string;
            /**
             * step, limit, quarantine, release, tenant or operator.
             */
            kind: string;
            from: string | null;
            to: string | null;
            reasons: Array<string>;
            limitFrom: number | null;
            limitTo: number | null;
        }>;
    };
    /**
     * "Request a higher limit" is approved automatically with a score of 90 or more on each of the last 14 days, no warn, restrict or pause in 30 days, and a request of at most 25,000 a day. Anything else goes to a person.
     */
    limitRequest: {
        eligibleForAutoApproval: boolean;
        /**
         * Why not, when not.
         */
        reasons: Array<{
            code: string;
            message: string;
        }>;
        maxAuto: number;
        requested: number | null;
    };
};

export type SupportBilling = {
    /**
     * False until billing is enabled on this installation.
     */
    available: boolean;
    data: Array<{
        workspaceId: string;
        account: {
            [key: string]: unknown;
        } | null;
        /**
         * The latest 50 ledger entries: top-ups, usage, refunds, disputes, credits.
         */
        ledger: Array<{
            [key: string]: unknown;
        }>;
    }>;
};

export type SupportRequestLog = {
    /**
     * False when this installation does not read Workers Logs (reason not_configured) or they did not answer (unavailable).
     */
    available: boolean;
    reason?: 'not_configured' | 'unavailable';
    window: {
        since: string;
        until: string;
    };
    /**
     * How long Workers Logs keep request lines.
     */
    retention: '3 days';
    /**
     * At most 50, most frequent first.
     */
    groups: Array<SupportRequestGroup>;
    totals: {
        /**
         * Matching request lines in the window.
         */
        errors: number;
        /**
         * More than 1,000 lines matched, so the counts are of a sample spread over the window: narrow it.
         */
        truncated: boolean;
    };
    computedAt: string;
};

export type SupportRequestGroup = {
    /**
     * The route template (/v1/emails/:id), never a path.
     */
    route: string;
    method: string;
    status: number;
    /**
     * The error code Nightmail answered with.
     */
    code: string | null;
    /**
     * How the caller authenticated: dashboard, apiKey, mcp, agentToken, inboxKey…; never which key or user.
     */
    principal: string;
    count: number;
    firstSeen: string;
    lastSeen: string;
    /**
     * Up to 5 of the latest, to look up with /v1/support/requests/{requestId}.
     */
    sampleRequestIds: Array<string>;
};

export type SupportRequestTrace = {
    requestId: string;
    /**
     * Whether Nightmail logged or stored anything about this request for this customer.
     */
    found: boolean;
    /**
     * Its request lines from Workers Logs (the last 3 days), in the grant’s workspaces. Successful requests are sampled, so one may be missing.
     */
    logs: Array<{
        at: string;
        route: string;
        method: string;
        status: number;
        code: string | null;
        durationMs: number | null;
        /**
         * How the caller authenticated: dashboard, apiKey, mcp, agentToken, inboxKey…; never which key or user.
         */
        principal: string;
        workspaceId: string;
    }>;
    /**
     * False when this installation does not read Workers Logs or they did not answer; logs is then empty.
     */
    logsAvailable: boolean;
    /**
     * Changes the request made.
     */
    auditEvents: Array<AuditEntry>;
    /**
     * Campaign launches the request started.
     */
    campaigns: Array<{
        workspaceId: string;
        id: string;
        name: string;
        state: string;
        error?: unknown;
    }>;
    /**
     * Routing versions the request wrote.
     */
    routingVersions: Array<{
        workspaceId: string;
        version: number;
        resourceId: string;
        at: string;
    }>;
    note: string;
};

export type SupportDeliveryMetrics = {
    workspaceId: string;
    computedAt: string;
    window: {
        since: string;
        until: string;
        granularity: 'day' | 'hour';
    };
    groupBy: 'none' | 'campaign' | 'from_domain' | 'provider' | 'stream';
    stream: 'all' | 'transactional' | 'marketing';
    filters: {
        campaignId: string | null;
        fromDomain: string | null;
    };
    totals: {
        /**
         * Real emails created (simulated mail is counted apart).
         */
        emails: number;
        /**
         * Accepted by the provider (SES).
         */
        accepted: number;
        delivered: number;
        hardBounced: number;
        /**
         * Delayed or soft-bounced at least once.
         */
        softBounced: number;
        complained: number;
        /**
         * Opened at least once, bots and privacy proxies included.
         */
        opened: number;
        /**
         * Opened with an open SES did not flag as a bot.
         */
        openedHuman: number;
        clicked: number;
        /**
         * Refused by the content screen.
         */
        screenRejected: number;
        suppressed: number;
        simulated: number;
        /**
         * Recipient unsubscribes (footer, one-click, SES) in the window, for the whole workspace: stream, campaignId and fromDomain do not narrow them.
         */
        unsubscribed: number;
        rates: SupportRates;
    };
    /**
     * Every bucket with mail, oldest first: the volume per day or hour.
     */
    buckets: Array<{
        /**
         * UTC day (YYYY-MM-DD) or hour (ISO).
         */
        at: string;
        /**
         * Real emails created (simulated mail is counted apart).
         */
        emails: number;
        /**
         * Accepted by the provider (SES).
         */
        accepted: number;
        delivered: number;
        hardBounced: number;
        /**
         * Delayed or soft-bounced at least once.
         */
        softBounced: number;
        complained: number;
        /**
         * Opened at least once, bots and privacy proxies included.
         */
        opened: number;
        /**
         * Opened with an open SES did not flag as a bot.
         */
        openedHuman: number;
        clicked: number;
        /**
         * Refused by the content screen.
         */
        screenRejected: number;
        suppressed: number;
        simulated: number;
        unsubscribed: number;
    }>;
    /**
     * Null when groupBy=none.
     */
    groups: Array<{
        /**
         * Campaign ID ("" for mail outside campaigns), From domain, provider or recipient domain, or stream.
         */
        key: string;
        /**
         * The groups beyond the largest 20, summed.
         */
        other: boolean;
        provider: 'gmail' | 'microsoft' | 'yahoo' | 'apple' | 'proton' | 'gmx' | 'other' | null;
        /**
         * Real emails created (simulated mail is counted apart).
         */
        emails: number;
        /**
         * Accepted by the provider (SES).
         */
        accepted: number;
        delivered: number;
        hardBounced: number;
        /**
         * Delayed or soft-bounced at least once.
         */
        softBounced: number;
        complained: number;
        /**
         * Opened at least once, bots and privacy proxies included.
         */
        opened: number;
        /**
         * Opened with an open SES did not flag as a bot.
         */
        openedHuman: number;
        clicked: number;
        /**
         * Refused by the content screen.
         */
        screenRejected: number;
        suppressed: number;
        simulated: number;
        rates: SupportRates;
        buckets: Array<{
            /**
             * UTC day (YYYY-MM-DD) or hour (ISO).
             */
            at: string;
            /**
             * Real emails created (simulated mail is counted apart).
             */
            emails: number;
            /**
             * Accepted by the provider (SES).
             */
            accepted: number;
            delivered: number;
            hardBounced: number;
            /**
             * Delayed or soft-bounced at least once.
             */
            softBounced: number;
            complained: number;
            /**
             * Opened at least once, bots and privacy proxies included.
             */
            opened: number;
            /**
             * Opened with an open SES did not flag as a bot.
             */
            openedHuman: number;
            clicked: number;
            /**
             * Refused by the content screen.
             */
            screenRejected: number;
            suppressed: number;
            simulated: number;
        }>;
    }> | null;
    /**
     * What the Hosted content screen judged in the window, for the whole workspace (not narrowed by the filters).
     */
    screen: {
        screened: number;
        rejected: number;
    };
    /**
     * Heuristics computed from this read, most severe first (support-agent-design §5.3). Weigh them; they are not verdicts.
     */
    findings: Array<SupportFinding>;
};

export type SupportRates = {
    delivery: SupportRate;
    bounce: SupportRate & unknown;
    complaint: SupportRate & unknown;
    open: SupportRate & unknown;
    openHuman: SupportRate & unknown;
    click: SupportRate & unknown;
};

/**
 * delivered / accepted
 */
export type SupportRate = {
    numerator: number;
    denominator: number;
    /**
     * A fraction; null when the denominator is zero.
     */
    value: number | null;
};

export type SupportFinding = {
    severity: 'info' | 'notice' | 'serious' | 'critical';
    code: string;
    /**
     * Plain words with the numbers; the usual cause and fix.
     */
    message: string;
    /**
     * The provider, domain, campaign or list it is about, or null for the whole read.
     */
    scope: string | null;
    /**
     * The numbers behind it: counts, rates as fractions, thresholds.
     */
    evidence: {
        [key: string]: number;
    };
};

export type SupportBounceReasons = {
    workspaceId: string;
    computedAt: string;
    window: {
        since: string;
        until: string;
    };
    /**
     * At most 50 groups, largest first.
     */
    groups: Array<{
        provider: 'gmail' | 'microsoft' | 'yahoo' | 'apple' | 'proton' | 'gmx' | 'other';
        /**
         * The recipient domain when the provider is other.
         */
        domain: string | null;
        class: 'bounce' | 'soft_bounce' | 'deferral' | 'complaint';
        /**
         * Bounce type/subtype (Permanent/General, Transient/MailboxFull…), delay type, or complaint feedback type.
         */
        subtype: string;
        /**
         * Enhanced status code (5.1.1, 5.7.26, 4.7.0…) when the event recorded one.
         */
        status: string | null;
        /**
         * The redacted diagnostic (addresses are <address>, IPs <ip>), 160 characters.
         */
        diagnostic: string | null;
        count: number;
        firstSeen: string;
        lastSeen: string;
        /**
         * Up to 3 campaigns with most of these.
         */
        campaigns: Array<string>;
    }>;
    /**
     * What the 50 groups leave out.
     */
    other: {
        groups: number;
        count: number;
    } | null;
    complaints: Array<{
        feedbackType: string;
        count: number;
    }>;
    /**
     * Hard bounces of first sends: a bad import stands out here.
     */
    firstSend: SupportRate & {
        basis: string;
    };
    /**
     * Heuristics computed from this read, most severe first (support-agent-design §5.3). Weigh them; they are not verdicts.
     */
    findings: Array<SupportFinding>;
};

export type SupportDomainHealth = {
    workspaceId: string;
    computedAt: string;
    domain: {
        id: string;
        name: string;
        region: string | null;
        createdAt: string | null;
    };
    /**
     * What Nightmail stored at the last verification.
     */
    claim: {
        sending: string | null;
        dkim: string | null;
        dkimSigning: boolean;
        mailFrom: {
            domain: string | null;
            status: string | null;
        };
        dmarc: {
            status: string | null;
            record: string | null;
            source: string | null;
            checkedAt: string | null;
        };
        receiving: string | null;
        lostSince: string | null;
        /**
         * shared (Nightmail Hosted pool) or byo.
         */
        connection: {
            kind: string;
            region: string;
        } | null;
    };
    /**
     * One live read of public DNS (5 labels, 3 seconds, cached 5 minutes).
     */
    dns: {
        checkedAt: string;
        /**
         * False when a lookup did not answer within the 3-second budget.
         */
        complete: boolean;
        spf: {
            record: string | null;
            /**
             * More than one SPF record is a permerror.
             */
            records: number;
            includesAmazonSes: boolean;
            /**
             * DNS-querying terms in the record itself (receivers allow 10 in all).
             */
            lookups: number;
            /**
             * -all, ~all, ?all…
             */
            all: string | null;
        };
        dmarc: {
            record: string | null;
            /**
             * stored: the exact label had none; this is the last verification’s record (it may be the organizational domain’s).
             */
            source: 'live' | 'stored' | null;
            at: string | null;
            p: string | null;
            sp: string | null;
            pct: number | null;
            adkim: string;
            aspf: string;
            rua: boolean;
            ruf: boolean;
            valid: boolean;
        };
        bimi: {
            record: string | null;
            /**
             * l= present
             */
            logo: boolean;
            /**
             * a= present (VMC or CMC)
             */
            authority: boolean;
        };
        mailFrom: {
            domain: string;
            mx: Array<string>;
            mxExpected: string;
            spf: {
                record: string | null;
                /**
                 * More than one SPF record is a permerror.
                 */
                records: number;
                includesAmazonSes: boolean;
                /**
                 * DNS-querying terms in the record itself (receivers allow 10 in all).
                 */
                lookups: number;
                /**
                 * -all, ~all, ?all…
                 */
                all: string | null;
            };
        } | null;
    };
    alignment: {
        /**
         * DKIM d= is the From domain (SES Easy DKIM verified and signing).
         */
        dkim: boolean;
        /**
         * The Return-Path (verified MAIL FROM) shares the From domain’s organizational domain.
         */
        spf: boolean;
        dmarcPasses: boolean;
        verdict: 'aligned' | 'dkim_only' | 'spf_only' | 'unaligned';
        returnPath: string;
    };
    volume: {
        /**
         * Days with mail in the last 30, oldest first.
         */
        days: Array<{
            at: string;
            emails: number;
            accepted: number;
            campaign: number;
        }>;
        /**
         * The first send kept (30 days): the warm-up age, unless olderThanRetention.
         */
        firstSendAt: string | null;
        olderThanRetention: boolean;
        warmupAgeDays: number | null;
        peakDaily: number;
        medianDaily: number;
        peakToMedian: number | null;
    };
    streams: {
        emails: number;
        campaign: number;
        /**
         * kind=marketing sends through the API.
         */
        marketingApi: number;
        marketingShare: SupportRate;
        /**
         * How marketing from this domain gets List-Unsubscribe.
         */
        listUnsubscribe: string;
        /**
         * One subject to more than 500 recipients a day outside campaigns.
         */
        bulkLikeTransactional: Array<{
            day: string;
            subject: string;
            emails: number;
        }>;
    };
    /**
     * Heuristics computed from this read, most severe first (support-agent-design §5.3). Weigh them; they are not verdicts.
     */
    findings: Array<SupportFinding>;
};

